/* prompt starters */
.ps-grid{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line);border-bottom:1px solid var(--line)}
.ps-card{display:flex;flex-direction:column;align-items:flex-start;gap:8px;padding:14px;background:var(--panel);text-align:left;transition:background-color .25s,color .25s}
.ps-card:hover{background:var(--accent-fill)}
.ps-card.on{background:var(--accent-fill);box-shadow:inset 0 0 0 1px var(--accent)}
.ps-card .ms{color:var(--accent)}
.ps-card .t{font-weight:600;font-size:14px}
.ps-card .d{font-size:12px;color:var(--muted);line-height:1.45}
.ps-comp{display:flex;align-items:flex-end;gap:10px;padding:12px}
.ps-text{flex:1;min-height:42px;font-size:14px;line-height:1.5;padding:4px}
.ps-caret{display:inline-block;width:6px;height:15px;background:var(--accent);vertical-align:-2px;margin-left:1px;animation:blinkc 1s steps(1) infinite}

/* ---------- prompt starters ---------- */
{
  const grid = $('#ps-grid'), text = $('#ps-text'), send = $('#ps-send');
  const sets = [
    [['dashboard','Audit a page','Audit the pricing page for spacing and contrast issues'],['edit_note','Rewrite copy','Rewrite the onboarding intro so it is shorter and clearer'],['code','Export tokens','Export the colour and spacing tokens as CSS variables'],['grid_on','Compare frames','Compare the mobile and desktop frames and list the differences']],
    [['search','Research competitors','Summarise how three competitors present their pricing'],['checklist','QA before launch','Run a launch checklist on the marketing site'],['person','Prep a client call','Draft an agenda for the kickoff call with the web team'],['history','Summarise changes','Summarise what changed in the design file this week']]
  ];
  let si = 0, typing = null;
  function render(first){
    const change = () => {
      grid.innerHTML = sets[si].map((s, i) => `<button class="ps-card ${first ? '' : 'enter'}" style="animation-delay:${i * 60}ms" data-i="${i}">${ic(s[0],'sm')}<span class="t">${s[1]}</span><span class="d">${s[2]}</span></button>`).join('');
      $$('.ps-card', grid).forEach(b => b.addEventListener('click', () => pick(+b.dataset.i, b)));
    };
    if (first) return change();
    grid.style.transition = 'opacity .2s'; grid.style.opacity = '0';
    setTimeout(() => { change(); grid.style.opacity = '1'; }, 200);
  }
  function pick(i, b){
    $$('.ps-card', grid).forEach(x => x.classList.toggle('on', x === b)); Sound.play('select');
    clearInterval(typing); const full = sets[si][i][2]; let n = 0; text.innerHTML = '<span class="ps-caret"></span>'; send.disabled = true;
    typing = setInterval(() => {
      n += 2; text.innerHTML = full.slice(0, n) + '<span class="ps-caret"></span>';
      if (n % 6 === 0) Sound.play('stream');
      if (n >= full.length){ clearInterval(typing); text.textContent = full; send.disabled = false; }
    }, reduce ? 0 : 18);
  }
  send.addEventListener('click', () => { Sound.play('send'); showToast('Sent'); text.innerHTML = '<span class="vc-ph">Pick a starter or type your own</span>'; send.disabled = true; $$('.ps-card', grid).forEach(x => x.classList.remove('on')); });
  $('#ps-shuffle').addEventListener('click', () => { si = (si + 1) % sets.length; Sound.play('tab'); render(); });
  render(true);
}
